const d = $input.first().json;
const c = d.current || {};
const day = (d.daily) || {};
const max = Array.isArray(day.temperature_2m_max) ? day.temperature_2m_max[0] : '--';
const min = Array.isArray(day.temperature_2m_min) ? day.temperature_2m_min[0] : '--';
const codes = {0:'Despejado',1:'Mayormente despejado',2:'Parcialmente nublado',3:'Nublado',45:'Niebla',48:'Niebla',51:'Llovizna ligera',61:'Lluvia ligera',63:'Lluvia',65:'Lluvia fuerte',80:'Chubascos',95:'Tormenta'};
const estado = codes[c.weather_code] || 'Variable';
const fecha = new Date().toLocaleDateString('es-BO', { timeZone: 'America/La_Paz', weekday: 'long', day: 'numeric', month: 'long' });
const tips = [
  'Responde a tus clientes en menos de 5 minutos: triplica la tasa de cierre.',
  'Automatiza 1 tarea repetitiva hoy y recupera horas cada semana.',
  'Un seguimiento extra cierra mas ventas que un cliente nuevo.',
  'Pide una resena a tu ultimo cliente feliz: prueba social gratis.',
  'Bloquea 1 hora sin notificaciones para lo importante, no lo urgente.',
  'Manda hoy 3 mensajes a prospectos que quedaron en visto.',
  'Revisa tu producto estrella: subir 10% el precio puede no bajar ventas.'
];
const tip = tips[new Date().getDate() % tips.length];
let msg = '☀️ <b>Tu Asistente ONIA — ' + fecha + '</b>\n\n';
msg += '🌡️ <b>Clima Santa Cruz:</b> ' + (c.temperature_2m ?? '--') + '°C, ' + estado + '\n';
msg += '   Maxima ' + max + '°C · Minima ' + min + '°C · Viento ' + (c.wind_speed_10m ?? '--') + ' km/h\n\n';
msg += '💡 <b>Tip del dia:</b> ' + tip + '\n\n';
msg += '🤖 <i>Este mensaje llega solo, todas las mananas. ONIA puede armar uno asi para tu negocio: clima, agenda, ventas del dia, recordatorios y mas.</i>';
return [{ json: { mensaje: msg } }];
